<script setup>
import {reactive} from 'vue';import {Head,router,useForm} from '@inertiajs/vue3';import AppLayout from '../../Layouts/AppLayout.vue';import PageBanner from '../../Components/PageBanner.vue';defineOptions({layout:AppLayout});const p=defineProps({request:Object,role:String,locations:Array});const approval=useForm({approve:true,note:''});const localNow=()=>new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);const issue=reactive({receiver_name:'',issued_at:localNow(),idempotency_key:p.request.idempotency_key,lines:p.request.lines.filter(x=>['READY','PARTIALLY_ISSUED'].includes(x.status)).map(x=>({enabled:true,line_id:x.id,quantity:Math.max(1,x.quantity-x.issued),vendor_item_id:x.buckets[0]?.vendor_item_id||null,location_id:x.buckets[0]?.location_id||null}))});const ready=(line,status)=>router.post(line.readiness_url,{status});const postIssue=()=>router.post(p.request.issue_url,{...issue,lines:issue.lines.filter(x=>x.enabled).map(({enabled,...x})=>x)});
</script>
<template><Head :title="request.number"/><div class="units-page"><PageBanner :title="request.number" :description="`${request.applicant} · ${request.department} · ${request.status}`" icon="box"/><section class="surface-card"><h2>Detail permintaan</h2><p>NRP {{request.nrp}} · {{request.phone}} · Dibutuhkan {{request.needed_at}}</p><p>{{request.purpose}}</p><div class="table-scroll"><table class="data-table"><thead><tr><th>Barang</th><th>Jenis</th><th>Diminta</th><th>Diserahkan</th><th>Status</th><th v-if="role==='warehouse'">Persiapan</th></tr></thead><tbody><tr v-for="line in request.lines" :key="line.id"><td>{{line.item}}</td><td>{{line.ownership}}</td><td>{{line.quantity}}</td><td>{{line.issued}}</td><td>{{line.status}}</td><td v-if="role==='warehouse'"><button class="text-button" @click="ready(line,'PREPARING')">Siapkan</button><button class="text-button" @click="ready(line,'READY')">Ready</button></td></tr></tbody></table></div></section><section v-if="role==='admin'" class="surface-card form-stack"><h2>Approval Admin</h2><textarea v-model="approval.note" class="form-input" placeholder="Catatan keputusan"/><div class="form-actions"><button class="button button--primary" @click="approval.transform(d=>({...d,approve:true})).post(request.approve_url)">Setujui</button><button class="button button--danger" @click="approval.transform(d=>({...d,approve:false})).post(request.approve_url)">Tolak</button></div></section><section v-if="role==='warehouse'" class="surface-card form-stack"><h2>Posting Data Out</h2><p>Hanya barang berstatus Ready yang tampil. STOCK dicatat sebagai penyerahan tanpa mengubah saldo web.</p><input v-model="issue.receiver_name" class="form-input" placeholder="Nama penerima"/><input v-model="issue.issued_at" type="datetime-local" class="form-input"/><div v-for="line in issue.lines" :key="line.line_id" class="form-grid"><label><input v-model="line.enabled" type="checkbox"/> {{request.lines.find(x=>x.id===line.line_id)?.item}}</label><input v-model="line.quantity" type="number" min="1" step="1" class="form-input" :disabled="!line.enabled"/></div><button class="button button--primary" :disabled="!issue.lines.some(x=>x.enabled)" @click="postIssue">Posting serah terima</button></section></div></template>
